1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
9	
10	/**
11	 * Rejects a create-owner body that is missing or blank in any required field before
12	 * {@link BuildOwner} runs. Runs after {@link NormalizeOwnerAddress} has canonicalized the
13	 * body, so the address check sees the normalized value and an address that is blank only
14	 * after normalization is rejected here.
15	 */
16	public class ValidateOwnerFields {
17	
18	    public void service(@Val OwnerFieldsDto request) throws MissingOwnerFieldsException {
19	        List<String> missing = new ArrayList<>();
20	        require(missing, "firstName", request.getFirstName());
21	        require(missing, "lastName", request.getLastName());
22	        require(missing, "address", request.getAddress());
23	        require(missing, "city", request.getCity());
24	        require(missing, "telephone", request.getTelephone());
25	        if (!missing.isEmpty()) {
26	            throw new MissingOwnerFieldsException(missing);
27	        }
28	    }
29	
30	    private static void require(List<String> missing, String field, String value) {
31	        if (value == null || value.isBlank()) {
32	            missing.add(field);
33	        }
34	    }
35	}
